/** 
 * @since 4.4
 */
public Batch executeTask(Map<String,String> analysisProperties,Object... components){
  try {
    checkStarted();
    configureTaskLogging(analysisProperties);
    bootstrapContainer.executeTask(analysisProperties,components);
    configureLogging();
    return this;
  } catch (IllegalStateException e) {
    throw new IllegalStateException("Batch execution failed due to invalid state: " + e.getMessage(), e);
  } catch (NullPointerException e) {
    throw new NullPointerException("Batch execution failed due to null value: " + e.getMessage());
  }
}
